  // add-to-cart | buy-it-now
  if (!customElements.get('product-form')) {
    customElements.define('product-form', class ProductForm extends HTMLElement {
      constructor() {
        super();

        // url链接，携带的【产品推荐】标签
        this.recommendedTag = getUrlQueryParams('action_tag') || ''

        this.form = this.querySelector('form');
        this.form.querySelector('[name=id]').disabled = false;
        this.form.addEventListener('submit', (e) => {
          e?.preventDefault();
          // 变体需要免税弹窗确认
          if (this.currentVariant?.open_tax_free_popup_before_buy) {
            try {
              this.showTaxFreePopup(() => this.onSubmitHandler())
            } catch (err) {
              this.onSubmitHandler()
            }
          } else {
            this.onSubmitHandler()
          }
        });
        this.cart = document.querySelector('cart-notification') || document.querySelector('cart-drawer');
        this.submitButton = this.querySelector('[type="submit"]');
        this.hideErrors = this.dataset.hideErrors === 'true';

        this.currentVariant = document.querySelector("variant-fields")?.currentVariant

        // 捆绑销售
        this.dom__bundled = document.querySelector("#app-bundled-sale")
        this.buyItNowButton = this.form.querySelector('.buy-it-now-custom-btn')
        // 如果是自研的 Buy Now 按钮，则监听点击事件
        if (this.buyItNowButton) {
          this.buyItNowButton.addEventListener('click', (e) => {
            e?.preventDefault()
            // 变体需要免税弹窗确认
            if (this.currentVariant?.open_tax_free_popup_before_buy) {
              try {
                this.showTaxFreePopup(() => this.handleBuy())
              } catch (err) {
                this.handleBuy()
              }
            } else {
              this.handleBuy();
            }
          })
        }

        document.addEventListener('variantChangeEvent', (e) => {
          const currentVariant = e.detail.variant
          if (currentVariant) {
            this.currentVariant = currentVariant
          }
        })

        this.handleQuantityLimit()
      }

      getSelectedVariant() {
        if(!document.querySelector(".product-main-block")) return {};
        if(document.querySelector(".product-main-block").getAttribute("onltvariant") === "true") {
          return JSON.parse(document.querySelector('#selected-variant[type="application/json"]').textContent);
        }
      }

      handleQuantityLimit() {
        if(!this.currentVariant) {
          this.currentVariant = this.getSelectedVariant()
        }
        if(!document.querySelector(".product-info-container quantity-input input")) return
        const quantityField = document.querySelector(".product-info-container quantity-input input")
        if(!this.currentVariant.inventory_quantity) {
          quantityField.setAttribute("data-max", 1)
          quantityField.setAttribute("max", 1)
          return
        }
        quantityField.setAttribute("data-max", this.currentVariant.inventory_quantity)
        quantityField.setAttribute("max", this.currentVariant.inventory_quantity)

        if(this.currentVariant.inventory_quantity > 1) {
          document.querySelector(".product-info_block quantity-input .quantity__button[name='plus']") && document.querySelector(".product-info_block quantity-input .quantity__button[name='plus']").removeAttribute("disabled")
        }
      }

      // 数据埋码
      GAEvent(params) {
        window.dataLayer.push({ "event_parameters": null });
        window.dataLayer.push({
          "event":"ga4Event",
          "event_name":"products_details_page_user_clicks",
          "event_parameters":{
            "current_page": window.location.href, // current page url
            ...params
          }
        });
      }

      // 新checkout 埋码事件
      GABeginCheckoutEvent(params) {
        window.dataLayer.push({ "event_parameters": null });
        window.dataLayer.push({
          "event":"ga4Event",
          "event_name":"begin_checkout",
          "event_parameters":{
            "current_page": window.location.href, // current page url
            ...params
          }
        });
      }

      handleErrorMsg(msg) {
        const errWrapper = document.querySelector(".product-info-container .add_cart_error_wrapper")
        if(!errWrapper) return
        errWrapper.toggleAttribute('hidden', !msg);
        errWrapper.textContent = msg
      }

      // Add to cart
      onSubmitHandler() {
        if (this.submitButton.getAttribute('aria-disabled') === 'true') return;
        this.handleErrorMsg()
        this.submitButton.setAttribute('aria-disabled', true);
        this.submitButton.classList.add('loading');

        let items = [];
        const formData = new FormData(this.form);
        const id = formData.get('id');

        const quantity = document.querySelector('quantity-input[data-mian-product-quantity]')?.querySelector('input')?.value || 1;

        // add base product
        const baseProduct = {
          id: Number(id),
          quantity,
          properties: this.recommendedTag ? { Action: this.recommendedTag } : {}
        }
        items.push(baseProduct);



        // 选择了配件 or 推荐产品 先加购配件or推荐产品
        let accesorries_title_str = '' // 数据埋码，收集所有捆绑产品 title
        if (this.dom__bundled && this.dom__bundled.querySelectorAll(":checked").length > 0) {
          const variantSku = this.form.querySelector('[name=id]').dataset.sku
          this.dom__bundled.querySelectorAll(":checked").forEach(item => {
            const quantityInput = item.parentElement.parentElement.querySelector('[data-quantity-input]')
            accesorries_title_str += `${quantityInput.dataset.skuTitle}*${quantityInput.value}*${quantityInput.dataset.skuPrice},`

            items.push({
              id: quantityInput.dataset.skuId,
              quantity: quantityInput.value,
              properties: {
                'Action': this.recommendedTag ? `bundled sale, ${this.recommendedTag}` : 'bundled sale',
                'bundled-sku': variantSku,
              }
            })
          })
        }

        shopifyCartAdd({ items }).then((r) => {
          if(this.cart) {
            this.cart.renderContents(r)
          } else {
            window.location.href = '/cart'
          }
          this.submitButton.classList.remove('loading');
          if (this.cart && this.cart.classList.contains('is-empty')) this.cart.classList.remove('is-empty');
          if (!this.error) this.submitButton.removeAttribute('aria-disabled');
          // 数据埋码
          this.GAEvent({
            "product_spu_name": $('.product__title').text(), //识别页面产品spu标题名称text
            "module": "Product Selection",//固定模块命名Product Selection
            "options": this.currentVariant?.title, //主体产品sku文本text
            "quantity": document.querySelector('quantity-input[data-mian-product-quantity]')?.querySelector('input')?.value, // 识别主体产品加购数量
            "add_on": `${accesorries_title_str.substring(0, accesorries_title_str.length -1)}`, //捆绑产品sku文本text，格式为：“产品sku文本text*数量*价格，产品sku文本text*数量*价格，产品sku文本text*数量*价格，...”
            "options_price": formatMoney(this.currentVariant?.price, window?.pageInfo?.currency?.money_format), //主体产品现价（黑色字体价格），当地货币
            "button_name": $('.product-form__submit[type="submit"]')?.text()?.trim(), // 识别加购add to cart/buy it now按钮 文本名称，根据业务配置的文本呈现
          })
        }).catch(err => {
          this.handleErrorMsg(err.statusText)
          this.submitButton.classList.remove('loading');
          if (this.cart && this.cart.classList.contains('is-empty')) this.cart.classList.remove('is-empty');
          if (!this.error) this.submitButton.removeAttribute('aria-disabled');
        })
      }

      // Buy it now
      async handleBuy() {
        let items = []
        let str = '' // 容错处理

        let main_sku_quantity = 1 // 数据埋码 主体产品加购数量
        let accesorries_title_str = '' // 数据埋码，收集所有捆绑产品 title

        // 当前商品变体 ID
        const variantId = this.form.querySelector('[name=id]').value


        // 如果 配置了 数量选择器，则取实时数量
        if (document.querySelector('quantity-input[data-mian-product-quantity]')) {
          main_sku_quantity = document.querySelector('quantity-input[data-mian-product-quantity]').querySelector('input').value
          items.push({
            id: variantId,
            quantity: main_sku_quantity,
            properties: this.recommendedTag ? { Action: this.recommendedTag } : {}
          })
          str = `/cart/${variantId}:${main_sku_quantity},`
        } else {
          main_sku_quantity = 1
          items.push({
            id: variantId,
            quantity: 1,
            properties: this.recommendedTag ? { Action: this.recommendedTag } : {}
          })
          str = `/cart/${variantId}:1,`
        }

        const properties = window.btoa(unescape(encodeURIComponent(JSON.stringify({
          Action: this.recommendedTag ? `bundled sale, ${this.recommendedTag}` : 'bundled sale'
        }))))

        if (this.dom__bundled && this.dom__bundled.querySelectorAll(":checked").length > 0) {
          this.dom__bundled.querySelectorAll(":checked").forEach(item => {
            const quantityInput = item.parentElement.parentElement.querySelector('[data-quantity-input]')
            items.push({
              id: quantityInput.dataset.skuId,
              quantity: quantityInput.value,
              properties: { Action: this.recommendedTag ? `bundled sale, ${this.recommendedTag}` : 'bundled sale' }
            })
            str += `${quantityInput.dataset.skuId}:${quantityInput.value},`
            accesorries_title_str += `${quantityInput.dataset.skuTitle}*${quantityInput.value}*${quantityInput.dataset.skuPrice},`
          })
        }


        try {
          // 生成 checkout url，并跳转
          const checkoutUrl = await createCartAndCheckout(items)
          if (checkoutUrl) {
            window.location.href = checkoutUrl
          }
        } catch (err) {
          // 容错处理
          if (this.dom__bundled && this.dom__bundled.querySelectorAll(":checked").length > 0) {
            str = `${str.substring(0, str.length -1)}?traffic_source=buy_now&properties=${properties}`
          } else {
            str = `${str.substring(0, str.length -1)}?traffic_source=buy_now`
          }
          window.location.href = str
        } finally {
          // 数据埋码
          this.GAEvent({
            "product_spu_name": $('.product__title').text(), //识别页面产品spu标题名称text
            "module": "Product Selection",//固定模块命名Product Selection
            "options": this.currentVariant?.title, //主体产品sku文本text
            "quantity": main_sku_quantity, // 识别主体产品加购数量
            "add_on": `${accesorries_title_str.substring(0, accesorries_title_str.length -1)}`, //捆绑产品sku文本text，格式为：“产品sku文本text*数量*价格，产品sku文本text*数量*价格，产品sku文本text*数量*价格，...”
            "options_price": formatMoney(this.currentVariant?.price, window?.pageInfo?.currency?.money_format), //主体产品现价（黑色字体价格），当地货币
            "button_name": $('.buy-it-now-custom-btn')?.text()?.trim(), // 识别加购add to cart/buy it now按钮 文本名称，根据业务配置的文本呈现
          })

          // 新 checkout 数据埋码
          this.GABeginCheckoutEvent({
            "module": $('.product__title').text(), //识别页面产品spu标题名称text
            "position": this.currentVariant?.title, //主体产品sku文本text
            "accesorries": `${accesorries_title_str.substring(0, accesorries_title_str.length -1)}`, //  捆绑产品sku文本text
            "button_name": "BUY IT NOW", //  按钮固定文本名称
          })
        }
      }

      // 渲染免税弹窗DOM
      renderTaxFreePopup(data) {
        const { title, content, checkbox_text, checkbox_text_color, button_text } = data
        return `
          <h4>${title}</h4>
          <div class="content rte">${content}</div>
          <div class="footer">
            <label>
              <input type="checkbox" ${checkbox_text_color ? `style="border-color:${checkbox_text_color}"` : ""} />
              <span ${checkbox_text_color ? `style="color:${checkbox_text_color}"` : ""}>${checkbox_text}</span>
            </label>
            <button disabled="disabled" data-submit-button>${button_text}</button>
          </div>
        `
      }
      // 显示免税弹窗
      showTaxFreePopup(callback) {
        const scriptTag = document.querySelector('script[type="application/json"][id="tax-free-popup-json"]');
        if (scriptTag) {
          // 提取 JSON 数据并解析
          const data = JSON.parse(scriptTag.textContent)

          // 非空校验
          const isEmpty = p => p?.trim() == ''

          // 所有配置项都有值，才弹窗
          if (!isEmpty(data?.title) && !isEmpty(data?.content) && !isEmpty(data?.checkbox_text) && !isEmpty(data?.button_text)) {
            this.modalInstance = ZModle.getInstance(this.renderTaxFreePopup(data), {
              id: "product-detail-tax-free-dialog",
              class: "product-detail-tax-free-dialog",
              destroyOnClose: true,
              cb: (modal) => {
                const submitButton = modal.querySelector('[data-submit-button]')
                const checkbox = modal.querySelector('input[type="checkbox"]')
                const closeBtn = modal.querySelector('.close')

                // 替换关闭按钮的SVG为纯黑色图标
                closeBtn.innerHTML = `
                <svg width="40" height="40" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                  <path d="M18 6L6 18M6 6L18 18" stroke="#000000" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>
                </svg>`
              

                // 复选框变更事件
                checkbox.addEventListener('change', () => {
                  if (checkbox.checked) {
                    submitButton.removeAttribute('disabled')
                  } else {
                    submitButton.setAttribute('disabled', 'disabled')
                  }
                })

                // 提交按钮事件
                submitButton.onclick = () => {
                  if (!checkbox.checked) return

                  // 关闭弹窗
                  this.modalInstance?.closeModal()

                  // 回调
                  callback && callback()
                }
              }
            })
          } else {
            callback && callback()
          }
        } else {
          callback && callback()
        }
      }
    })
  }

